{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T011142Z/cell-qN4QYy/src/address.js","content":"/**
 * Cell address helpers: parsing an address-shaped word, converting a column
 * between its letters and its 1-based number, and enumerating the cells a
 * range covers.
 */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/**
 * Resolve a word (already known to be an identifier: a letter followed by
 * letters and/or digits) into a cell address, or return null when it is not
 * one or two letters followed by one to three digits naming a row of at
 * least 1.
 */
export function resolveAddressWord(word) {
  const match = ADDRESS_RE.exec(word)
  if (!match) return null
  const row = parseInt(match[2], 10)
  if (row < 1) return null
  const col = match[1].toUpperCase()
  return { col, row, key: col + String(row) }
}

/** Convert an uppercase column string (`A`..`ZZ`) to its 1-based number. */
export function colToNum(col) {
  let n = 0
  for (let i = 0; i < col.length; i++) {
    n = n * 26 + (col.charCodeAt(i) - 64)
  }
  return n
}

/** Convert a 1-based column number back to its uppercase letters. */
export function numToCol(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

/**
 * List the cell keys a range covers, in ascending column then ascending row
 * order, regardless of which corner each endpoint names. Returns null when
 * either endpoint is not an addressable cell.
 */
export function rangeCells(fromWord, toWord) {
  const a = resolveAddressWord(fromWord)
  const b = resolveAddressWord(toWord)
  if (!a || !b) return null
  const colMin = Math.min(colToNum(a.col), colToNum(b.col))
  const colMax = Math.max(colToNum(a.col), colToNum(b.col))
  const rowMin = Math.min(a.row, b.row)
  const rowMax = Math.max(a.row, b.row)
  const cells = []
  for (let c = colMin; c <= colMax; c++) {
    const col = numToCol(c)
    for (let r = rowMin; r <= rowMax; r++) {
      cells.push(col + String(r))
    }
  }
  return cells
}

/** Split a canonical cell key (e.g. `AA12`) back into its column and row. */
export function splitKey(key) {
  const match = /^([A-Z]{1,2})([0-9]+)$/.exec(key)
  return { col: match[1], row: parseInt(match[2], 10) }
}

/** Order two canonical cell keys by column then by row. */
export function compareKeys(a, b) {
  const pa = splitKey(a)
  const pb = splitKey(b)
  const ca = colToNum(pa.col)
  const cb = colToNum(pb.col)
  if (ca !== cb) return ca - cb
  return pa.row - pb.row
}
"}

