{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T011142Z/cell-qN4QYy/src/lexer.js","content":"/**
 * Tokenizer for a formula body (the content after the leading `=`).
 */

const TWO_CHAR_OPS = ['<=', '>=', '<>']
const ONE_CHAR_OPS = ['^', '*', '/', '+', '-', '=', '<', '>']

/** Thrown when a formula body does not lex or parse as the grammar allows. */
export class FormulaSyntaxError extends Error {}

/**
 * Turn a formula body into a flat list of tokens. Throws FormulaSyntaxError
 * on any character the grammar does not accept.
 */
export function lex(body) {
  const tokens = []
  let i = 0
  const n = body.length
  while (i < n) {
    const ch = body[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch >= '0' && ch <= '9') {
      let j = i + 1
      while (j < n && body[j] >= '0' && body[j] <= '9') j++
      if (body[j] === '.') {
        let k = j + 1
        if (k < n && body[k] >= '0' && body[k] <= '9') {
          while (k < n && body[k] >= '0' && body[k] <= '9') k++
          j = k
        }
      }
      tokens.push({ type: 'NUMBER', value: body.slice(i, j) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      let j = i + 1
      while (j < n && /[A-Za-z0-9]/.test(body[j])) j++
      tokens.push({ type: 'IDENT', value: body.slice(i, j) })
      i = j
      continue
    }
    if (ch === '(') {
      tokens.push({ type: 'LPAREN' })
      i++
      continue
    }
    if (ch === ')') {
      tokens.push({ type: 'RPAREN' })
      i++
      continue
    }
    if (ch === ',') {
      tokens.push({ type: 'COMMA' })
      i++
      continue
    }
    if (ch === ':') {
      tokens.push({ type: 'COLON' })
      i++
      continue
    }
    const two = body.slice(i, i + 2)
    if (TWO_CHAR_OPS.includes(two)) {
      tokens.push({ type: 'OP', value: two })
      i += 2
      continue
    }
    if (ONE_CHAR_OPS.includes(ch)) {
      tokens.push({ type: 'OP', value: ch })
      i++
      continue
    }
    throw new FormulaSyntaxError(`unexpected character ${ch}`)
  }
  return tokens
}
"}

