  const tok = peek(state)
  if (!tok) throw new FormulaSyntaxError('unexpected end of formula')

  if (tok.type === 'NUMBER') {
    state.pos++
    return { type: 'number', value: parseFloat(tok.value) }
  }

  if (tok.type === 'LPAREN') {
    state.pos++
    const inner = parseComparison(state)
    const close = peek(state)
    if (!close || close.type !== 'RPAREN') throw new FormulaSyntaxError('expected )')
    state.pos++
    return inner
  }

  if (tok.type === 'IDENT') {
    const upper = tok.value.toUpperCase()
    const next = state.tokens[state.pos + 1]
    if (next && next.type === 'LPAREN') {
      state.pos += 2
      const args = parseArgs(state)
      const close = peek(state)
      if (!close || close.type !== 'RPAREN') throw new FormulaSyntaxError('expected )')
      state.pos++
      return { type: 'call', name: upper, args }
    }
    state.pos++
    if (upper === 'TRUE') return { type: 'bool', value: true }
    if (upper === 'FALSE') return { type: 'bool', value: false }
    return { type: 'address', word: upper }
  }

  throw new FormulaSyntaxError('unexpected token')
}

function parseArgs(state) {
  const args = []
  const close = peek(state)
  if (close && close.type === 'RPAREN') return args
  args.push(parseArgument(state))
  while (peek(state) && peek(state).type === 'COMMA') {
    state.pos++
    args.push(parseArgument(state))
  }
