  const a = peek(state)
  const b = state.tokens[state.pos + 1]
  const c = state.tokens[state.pos + 2]
  if (a && a.type === 'IDENT' && b && b.type === 'COLON' && c && c.type === 'IDENT') {
    state.pos += 3
    return { type: 'range', from: a.value.toUpperCase(), to: c.value.toUpperCase() }
  }
  return parseComparison(state)
}
