 * Printing a value for the `values` command.
 */

/** Round to ten significant digits and print as JavaScript would. */
export function formatNumber(n) {
  if (n === 0) return '0'
  const rounded = Number(n.toPrecision(10))
  return String(rounded)
}

export function formatValue(v) {
  if (v.type === 'number') return formatNumber(v.value)
  if (v.type === 'text') return v.value
  if (v.type === 'bool') return v.value ? 'TRUE' : 'FALSE'
  return v.value
}
"}

