 * Parsing the sheet text into a map of declared cells.
 */

import { resolveAddressWord } from './address.js'

/** Raised for a malformed sheet; carries the exact message the CLI prints. */
export class SheetError extends Error {}

/**
 * Parse the sheet text into a Map from canonical address key to
 * `{ address, col, row, content }`. Throws SheetError on the first invalid
 * address or duplicate declaration.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const cells = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const stripped = lines[i].replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    const wsMatch = /[ \t]/.exec(stripped)
    let addressPart
    let content
    if (wsMatch) {
      addressPart = stripped.slice(0, wsMatch.index)
      let rest = stripped.slice(wsMatch.index)
      rest = rest.replace(/^[ \t]+/, '')
      content = rest
    } else {
      addressPart = stripped
      content = ''
    }

    const upper = addressPart.toUpperCase()
    const resolved = resolveAddressWord(upper)
    if (!resolved) {
      throw new SheetError(`error: line ${lineNo}: invalid cell address ${upper}`)
    }
    if (cells.has(resolved.key)) {
      throw new SheetError(`error: line ${lineNo}: cell ${resolved.key} is declared twice`)
    }
    cells.set(resolved.key, { address: resolved.key, col: resolved.col, row: resolved.row, content })
  }

  return cells
}
"}

