 * Evaluating a sheet's cells: literals, formula parsing, and the recursive
 * evaluator with memoization and cycle detection.
 */

import { parseFormula, FormulaSyntaxError, KNOWN_FUNCTIONS } from './parser.js'
import { resolveAddressWord, rangeCells } from './address.js'
import { num, text, bool, err, arithError, toPlainNumber, finite, compareValues, ERROR_TOKENS } from './values.js'

const NUMBER_LITERAL_RE = /^-?[0-9]+(\.[0-9]+)?$/

/** Parse a cell's literal content (never starting with `=`) into a value. */
function literalValue(content) {
  if (content === '') return num(0)
  if (NUMBER_LITERAL_RE.test(content)) return num(parseFloat(content))
  if (ERROR_TOKENS.includes(content)) return err(content)
  return text(content)
}

/**
 * Builds an evaluator over a parsed sheet, exposing `valueOf(key)` to get a
 * cell's value (defaulting undeclared cells to 0, and detecting cycles) and
 * caching the parsed AST for formula cells for deps to reuse.
 */
export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.astCache = new Map()
    this.valueCache = new Map()
    this.inProgress = new Set()
  }

  /** The parsed AST for a formula cell, or null for a literal or a bad parse. */
  astFor(key) {
    if (this.astCache.has(key)) return this.astCache.get(key)
    const cell = this.cells.get(key)
    let ast = null
    if (cell && cell.content.startsWith('=')) {
      try {
        ast = parseFormula(cell.content.slice(1))
      } catch (e) {
        if (!(e instanceof FormulaSyntaxError)) throw e
        ast = null
      }
    }
    this.astCache.set(key, ast)
    return ast
  }

  valueOf(key) {
    if (this.valueCache.has(key)) return this.valueCache.get(key)
    if (this.inProgress.has(key)) return err('#CYCLE!')

    const cell = this.cells.get(key)
    if (!cell) return num(0)

    this.inProgress.add(key)
    let result
    if (cell.content.startsWith('=')) {
      const ast = this.astFor(key)
      result = ast === null ? err('#ERR!') : this.evalNode(ast)
    } else {
      result = literalValue(cell.content)
    }
    this.inProgress.delete(key)
    this.valueCache.set(key, result)
    return result
  }

  /** Resolve a formula argument node to the flat list of values it contributes. */
  evalArgValues(node) {
    if (node.type === 'range') {
      const keys = rangeCells(node.from, node.to)
      if (!keys) return [err('#REF!')]
      return keys.map((k) => this.valueOf(k))
    }
    return [this.evalNode(node)]
  }

  evalNode(node) {
    switch (node.type) {
      case 'number':
        return num(node.value)
      case 'bool':
        return bool(node.value)
      case 'address': {
        const addr = resolveAddressWord(node.word)
        if (!addr) return err('#REF!')
        return this.valueOf(addr.key)
      }
      case 'unary': {
        const operand = this.evalNode(node.operand)
        const opErr = arithError(operand)
        if (opErr) return opErr
        const n = toPlainNumber(operand)
        return finite(node.op === '-' ? -n : n)
      }
      case 'binary':
        return this.evalBinary(node)
      case 'compare':
        return this.evalCompare(node)
      case 'call':
        return this.evalCall(node)
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }

  evalBinary(node) {
    const left = this.evalNode(node.left)
    const leftErr = arithError(left)
    if (leftErr) return leftErr
    const right = this.evalNode(node.right)
    const rightErr = arithError(right)
    if (rightErr) return rightErr
