 * Collecting the addresses a formula's AST names directly, for the `deps`
 * command.
 */

import { resolveAddressWord, rangeCells, compareKeys } from './address.js'

/** The distinct in-range addresses `ast` names directly, sorted by column then row. */
export function collectDeps(ast) {
  const keys = new Set()
  walk(ast, keys)
  return [...keys].sort(compareKeys)
}

function walk(node, keys) {
  switch (node.type) {
    case 'number':
    case 'bool':
      return
    case 'address': {
      const addr = resolveAddressWord(node.word)
      if (addr) keys.add(addr.key)
      return
    }
    case 'range': {
      const cells = rangeCells(node.from, node.to)
      if (cells) for (const k of cells) keys.add(k)
      return
    }
    case 'unary':
      walk(node.operand, keys)
      return
    case 'binary':
    case 'compare':
      walk(node.left, keys)
      walk(node.right, keys)
      return
    case 'call':
      for (const arg of node.args) walk(arg, keys)
      return
    default:
      throw new Error(`unknown node type ${node.type}`)
  }
}
"}

