/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseSheet, SheetError } from './sheet.js'
import { Evaluator } from './evaluator.js'
import { collectDeps } from './deps.js'
import { formatValue } from './format.js'
import { compareKeys } from './address.js'

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

async function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'values' && argv[0] !== 'deps')) {
    process.stderr.write('error: usage: cli.js values|deps\n')
    process.exit(2)
  }
  const mode = argv[0]

  const { createRequire } = await import('node:module')
  const require = createRequire(import.meta.url)
  const input = require('node:fs').readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      process.stderr.write(e.message + '\n')
      process.exit(2)
    }
    throw e
  }

  const keys = [...cells.keys()].sort(compareKeys)
  const lines = []

  if (mode === 'values') {
    const evaluator = new Evaluator(cells)
    for (const key of keys) {
      const value = evaluator.valueOf(key)
      lines.push(`${key}=${formatValue(value)}`)
    }
  } else {
    const evaluator = new Evaluator(cells)
    for (const key of keys) {
      const ast = evaluator.astFor(key)
      const depKeys = ast ? collectDeps(ast) : []
      lines.push(`${key}: ${depKeys.join(' ')}`.replace(/: $/, ':'))
    }
  }

  process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
}

main()
"}

